function registerUserAccountApi(router::HTTP.Router, impl; path_prefix::String="", optional_middlewares...)
    HTTP.register!(router, "GET", path_prefix * "/user_account/following/boards", OpenAPI.Servers.middleware(impl, boards_user_follows_list_read, boards_user_follows_list_validate, boards_user_follows_list_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/user_account/following/{username}", OpenAPI.Servers.middleware(impl, follow_user_update_read, follow_user_update_validate, follow_user_update_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/user_account/followers", OpenAPI.Servers.middleware(impl, followers_list_read, followers_list_validate, followers_list_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/user_account/businesses", OpenAPI.Servers.middleware(impl, linked_business_accounts_get_read, linked_business_accounts_get_validate, linked_business_accounts_get_invoke; optional_middlewares...))
    HTTP.register!(router, "DELETE", path_prefix * "/user_account/websites", OpenAPI.Servers.middleware(impl, unverify_website_delete_read, unverify_website_delete_validate, unverify_website_delete_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/user_account/analytics", OpenAPI.Servers.middleware(impl, user_account_analytics_read, user_account_analytics_validate, user_account_analytics_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/user_account/analytics/top_pins", OpenAPI.Servers.middleware(impl, user_account_analytics_top_pins_read, user_account_analytics_top_pins_validate, user_account_analytics_top_pins_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/user_account/analytics/top_video_pins", OpenAPI.Servers.middleware(impl, user_account_analytics_top_video_pins_read, user_account_analytics_top_video_pins_validate, user_account_analytics_top_video_pins_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/users/{username}/interests/follow", OpenAPI.Servers.middleware(impl, user_account_followed_interests_read, user_account_followed_interests_validate, user_account_followed_interests_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/user_account", OpenAPI.Servers.middleware(impl, user_account_get_read, user_account_get_validate, user_account_get_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/user_account/following", OpenAPI.Servers.middleware(impl, user_following_get_read, user_following_get_validate, user_following_get_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/user_account/websites", OpenAPI.Servers.middleware(impl, user_websites_get_read, user_websites_get_validate, user_websites_get_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/user_account/websites", OpenAPI.Servers.middleware(impl, verify_website_update_read, verify_website_update_validate, verify_website_update_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/user_account/websites/verification", OpenAPI.Servers.middleware(impl, website_verification_get_read, website_verification_get_validate, website_verification_get_invoke; optional_middlewares...))
    return router
end
